  "ru": <String, Object>{"ui": <String, Object>{"title": "Мой малыш", "typing": "печатает…", "placeholder": "Напиши сообщение…", "week": "{n}-я неделя", "size": "мой размер — {fruit}", "today": "Сегодня", "card_new": "Малыш написал тебе 💬", "card_wait": "Малыш сегодня ещё не написал… скоро 👀", "card_cta": "Ответить", "share_title": "Поделиться чатом", "share_sub": "Фото или видео, сообщение за сообщением. Пусть подруги тоже увидят 💛", "share_photo": "Фото", "share_video": "Видео", "share_making": "Готовим видео…", "share_text": "Мой малыш ещё не родился, но уже пишет мне 💛 Anacan", "share_error": "Не получилось поделиться. Попробуй ещё раз.", "hook": "Мой малыш ещё не родился… но уже пишет мне.", "end_line1": "Малыш пишет тебе", "end_line2": "каждый день.", "notif_title": "Мой малыш 💛", "about": "Просто для удовольствия: Anacan пишет сообщения по неделе твоего малыша.", "share_ready_video": "Твоё видео готово 🎉", "share_ready_photo": "Твоё фото готово 🎉", "share_now": "Поделиться", "save": "Сохранить", "care_text": "Поделись этим и со своим врачом, мама. Каждый твой вопрос важен 💛", "care_cta": "Спросить Anacan.AI"}, "openers": <String>["Мама! Угадай что 🖐", "Мама, ты не спишь? 👀", "Пссс… мама! 🤫", "Мама, можно я тебе кое-что скажу? 💛", "Привет, мама! 👋"], "notifications": <String>["Мама! Угадай что 🖐", "Я тебе кое-что написал 💬", "Пссс… мама, посмотри! 👀", "Ты не поверишь, что я хочу тебе сегодня рассказать! 💛"], "replies": <String, Object>{"love": <String>["Я тоже тебя люблю, мама 💛", "Я тебя ещё не видел, но уже так сильно люблю 🥰", "Мой размер пока — {fruit}, но сердечко полно тобой 💛"], "how": <String>["Отлично! Тут тепло и уютно 😌", "Всё хорошо, мама. Сегодня я ещё чуть-чуть подрос 🌱", "Прекрасно! Слушаю, как стучит твоё сердце 💓"], "size": <String>["Сейчас мой размер — примерно {fruit} 😄", "Во мне уже {cm} см! Расту 📏", "У меня {week}-я неделя, и я каждый день немножко расту 🌱"], "kick_early": <String>["Я уже шевелюсь, но я ещё такой крошечный, что ты не почувствуешь 🤭", "Я тут кувыркаюсь 🤸 Скоро ты это почувствуешь!"], "kick": <String>["Почувствовала? Это был я 🦶", "Я сегодня танцевал, ты почувствовала? 💃", "Этим пинком я сказал тебе привет 👋🦶"], "hear_early": <String>["Мои ушки ещё готовятся, но скоро я тебя услышу 👂", "Дай мне ещё немного подрасти, и я услышу твой голос 🥰"], "hear": <String>["Я тебя слышу, мама! Поговори со мной ещё 🥰", "Твой голос — моя любимая музыка 🎶", "Спой мне песенку, а я послушаю 🎵"], "food": <String>["Что бы ты ни съела, я тоже пробую 😋", "Может, сегодня поедим фруктов? 🍎", "Ммм, было вкусно! Ещё чуть-чуть? 😄"], "sleep": <String>["Я тоже хочу спать 😴 Давай отдохнём вместе", "Когда ты ложишься, я тоже расслабляюсь 😌", "Прости, если я танцую по ночам 🙈"], "dad": <String>["Передай папе привет от меня! 👋", "Я и папин голос знаю 😊", "Обожаю, когда папа разговаривает с твоим животиком 🥰"], "meet": <String>["Осталось недель: {weeks_left}, и мы встретимся! 🤗", "Я тоже хочу тебя увидеть! Дай мне ещё немножко подрасти 🌱", "Скоро мы встретимся 💛"], "meet_soon": <String>["Уже совсем скоро, мама! Я тоже готовлюсь 🤗", "Скоро я буду у тебя на ручках 💛"], "name": <String>["Как ты меня назовёшь? 😊 Выбери красивое имя!", "Любое имя прозвучит чудесно твоим голосом 💛"], "hello": <String>["Привет, мама! 👋", "Приве-е-ет! Я тебя ждал 💛"], "thanks": <String>["Пожалуйста, мама! 😊", "Спасибо, что носишь меня 💛"], "generic": <String>["Мама, ты самая лучшая 💛", "Я слушаю 👂😊", "Хм… спрошу об этом, когда подрасту 😄", "Я ещё маленький, но мне очень понравилось 😄", "Напиши мне ещё, мама! 🥰"], "care": <String>["Я так сильно тебя люблю, мама 💛", "Я всегда рядом с тобой 🤗"]}, "keywords": <String, Object>{"thanks": <String>["спасиб", "спс", "благодар", "пасиб"], "love": <String>["любл", "люб", "сердц", "солнышк", "зайк", "родн", "❤", "💛", "😘", "🥰"], "name": <String>["имя", "имен", "назов", "назва", "зовут"], "dad": <String>["пап", "папочк", "отец", "отц", "муж"], "kick": <String>["пина", "пинк", "толк", "шевел", "двига", "танц