  "zh": <String, Object>{"ui": <String, Object>{"title": "我的宝宝", "typing": "正在输入…", "placeholder": "写条消息…", "week": "第{n}周", "size": "像{fruit}那么大", "today": "今天", "card_new": "宝宝给你发消息啦 💬", "card_wait": "宝宝今天还没发消息…快了 👀", "card_cta": "回复", "share_title": "分享这段聊天", "share_sub": "可以分享图片，或逐条播放的视频。让朋友们也看看吧 💛", "share_photo": "图片", "share_video": "视频", "share_making": "正在生成视频…", "share_text": "我的宝宝还没出生，就给我发消息啦 💛 Anacan", "share_error": "分享失败，请重试。", "hook": "我的宝宝还没出生……却会给我发消息。", "end_line1": "宝宝每天", "end_line2": "都给你发消息。", "notif_title": "我的宝宝 💛", "about": "纯属娱乐：Anacan 会根据宝宝的孕周来写这些消息。", "share_ready_video": "你的视频准备好啦 🎉", "share_ready_photo": "你的图片准备好啦 🎉", "share_now": "分享", "save": "保存", "care_text": "妈妈，这个也和你的医生说一说吧。你的每个问题都很重要 💛", "care_cta": "问问 Anacan.AI"}, "openers": <String>["妈妈！你猜怎么着 🖐", "妈妈，你醒了吗？👀", "嘘……妈妈！🤫", "妈妈，我可以告诉你一件事吗？💛", "妈妈好！👋"], "notifications": <String>["妈妈！你猜怎么着 🖐", "我给你写了点东西 💬", "嘘……妈妈，快看！👀", "你肯定猜不到我今天想跟你说什么！💛"], "replies": <String, Object>{"love": <String>["我也爱你，妈妈 💛", "我还没见过你，可我已经好爱好爱你了 🥰", "我也许只有{fruit}那么大，可我的心里装满了你 💛"], "how": <String>["好极了！这里又暖和又舒服 😌", "我很好，妈妈。今天我又长大了一点点 🌱", "超好！我正在听你的心跳呢 💓"], "size": <String>["现在我大概有{fruit}那么大 😄", "我已经{cm}厘米啦！在长个子呢 📏", "我现在第{week}周了，每天都长大一点点 🌱"], "kick_early": <String>["我已经在扭来扭去了，可我还太小，你感觉不到 🤭", "我在这里翻小跟头呢 🤸 你很快就能感觉到啦！"], "kick": <String>["感觉到了吗？那是我哦 🦶", "我今天跳舞了，你感觉到了吗？💃", "刚才那一脚是我在跟你打招呼 👋🦶"], "hear_early": <String>["我的小耳朵还在准备中，很快就能听到你啦 👂", "等我再长大一点，就能听到你的声音了 🥰"], "hear": <String>["我听到你啦，妈妈！再跟我说说话吧 🥰", "你的声音是我最喜欢的音乐 🎶", "给我唱首歌吧，我会认真听的 🎵"], "food": <String>["你吃什么，我也能尝到一点点 😋", "今天我们吃点水果好不好？🍎", "嗯，真好吃！再来一点？😄"], "sleep": <String>["我也想睡觉了 😴 我们一起休息吧", "你一躺下，我也放松下来了 😌", "要是我半夜跳舞，对不起啦 🙈"], "dad": <String>["帮我跟爸爸问声好！👋", "我也认得爸爸的声音哦 😊", "我最喜欢爸爸对着你的肚子说话了 🥰"], "meet": <String>["再过{weeks_left}周我们就见面啦！🤗", "我也想见你！让我再长大一点 🌱", "我们很快就要见面啦 💛"], "meet_soon": <String>["快了快了，妈妈！我也在做准备呢 🤗", "很快我就能躺在你怀里啦 💛"], "name": <String>["你要给我取什么名字呀？😊 选个好听的吧！", "什么名字从你嘴里叫出来都好听 💛"], "hello": <String>["妈妈好！👋", "嗨～我一直在等你呢 💛"], "thanks": <String>["不客气，妈