: <String>["今天我有{fruit}那么大啦！我在长大 🌱", "你的心跳是我的摇篮曲 💓", "这里又暖和又舒服，别担心 😌", "今天休息一下吧，我也休息 😴", "别忘了喝水哦，我也喜欢 💧", "今天我们吃什么呀？😋", "笑一个嘛，妈妈！你一笑，我也放松了 😊", "帮我跟爸爸问声好！👋", "我虽然小小的，可我好爱好爱你 💛", "今天我又长大了一点点，你感觉到了吗？📏", "我每天都比昨天更爱你一点 🥰", "给我讲个故事好吗？📖", "妈妈，你今天真好看！✨", "我在等你，你也在等我 🤗"]},
  "id": <String, Object>{"ui": <String, Object>{"title": "Bayiku", "typing": "sedang mengetik…", "placeholder": "Tulis pesan…", "week": "Minggu {n}", "size": "seukuran {fruit}", "today": "Hari ini", "card_new": "Bayimu menulis pesan untukmu 💬", "card_wait": "Bayimu belum menulis hari ini… sebentar lagi 👀", "card_cta": "Balas", "share_title": "Bagikan obrolan ini", "share_sub": "Sebagai foto atau video per pesan. Biar teman-temanmu juga lihat 💛", "share_photo": "Foto", "share_video": "Video", "share_making": "Membuat video…", "share_text": "Bayiku belum lahir, tapi sudah kirim pesan ke aku 💛 Anacan", "share_error": "Gagal membagikan. Silakan coba lagi.", "hook": "Bayiku belum lahir… tapi sudah kirim pesan ke aku.", "end_line1": "Bayimu mengirimimu pesan", "end_line2": "setiap hari.", "notif_title": "Bayiku 💛", "about": "Hanya untuk seru-seruan: Anacan menulis pesan sesuai minggu kehamilan bayimu.", "share_ready_video": "Videomu sudah siap 🎉", "share_ready_photo": "Fotomu sudah siap 🎉", "share_now": "Bagikan", "save": "Simpan", "care_text": "Ceritakan ini juga ke doktermu ya, Mama. Setiap pertanyaanmu penting 💛", "care_cta": "Tanya Anacan.AI"}, "openers": <String>["Mama! Coba tebak 🖐", "Mama, sudah bangun? 👀", "Psst… Mama! 🤫", "Mama, boleh aku cerita sesuatu? 💛", "Hai Mama! 👋"], "notifications": <String>["Mama! Coba tebak 🖐", "Aku menulis sesuatu untuk Mama 💬", "Psst… Mama, lihat! 👀", "Mama nggak bakal percaya apa yang mau aku ceritakan hari ini! 💛"], "replies": <String, Object>{"love": <String>["Aku juga sayang Mama 💛", "Aku belum pernah lihat Mama, tapi aku sudah sayang banget 🥰", "Aku mungkin cuma seukuran {fruit}, tapi hatiku penuh dengan Mama 💛"], "how": <String>["Baik banget! Di sini hangat dan nyaman 😌", "Aku baik, Mama. Hari ini aku tumbuh sedikit lagi 🌱", "Senang sekali! Aku lagi dengar detak jantung Mama 💓"], "size": <String>["Sekarang aku kira-kira seukuran {fruit} 😄", "Aku sudah {cm} cm! Terus tumbuh 📏", "Aku di minggu ke-{week} dan tumbuh sedikit setiap h