  "fr": <String, Object>{"ui": <String, Object>{"title": "Mon bébé", "typing": "écrit…", "placeholder": "Écris un message…", "week": "Semaine {n}", "size": "ma taille : {fruit}", "today": "Aujourd'hui", "card_new": "Ton bébé t'a écrit 💬", "card_wait": "Ton bébé n'a pas encore écrit aujourd'hui… bientôt 👀", "card_cta": "Répondre", "share_title": "Partager cette discussion", "share_sub": "En photo ou en vidéo, message par message. Montre-la aussi à tes amies 💛", "share_photo": "Photo", "share_video": "Vidéo", "share_making": "Création de la vidéo…", "share_text": "Mon bébé n'est pas encore né, mais il m'écrit déjà 💛 Anacan", "share_error": "Impossible de partager. Réessaie, s'il te plaît.", "hook": "Mon bébé n'est pas encore né… mais il m'écrit déjà.", "end_line1": "Ton bébé t'écrit", "end_line2": "chaque jour.", "notif_title": "Mon bébé 💛", "about": "Juste pour le plaisir : Anacan écrit les messages selon la semaine de ton bébé.", "share_ready_video": "Ta vidéo est prête 🎉", "share_ready_photo": "Ta photo est prête 🎉", "share_now": "Partager", "save": "Enregistrer", "care_text": "Parles-en aussi à ton médecin, maman. Chaque question compte 💛", "care_cta": "Demander à Anacan.AI"}, "openers": <String>["Maman ! Devine quoi 🖐", "Maman, tu dors ? 👀", "Psst… maman ! 🤫", "Maman, je peux te dire un truc ? 💛", "Coucou maman ! 👋"], "notifications": <String>["Maman ! Devine quoi 🖐", "Je t'ai écrit un petit mot 💬", "Psst… maman, regarde ! 👀", "Tu ne vas pas croire ce que j'ai à te raconter aujourd'hui ! 💛"], "replies": <String, Object>{"love": <String>["Moi aussi je t'aime, maman 💛", "Je ne t'ai jamais vue, mais je t'aime déjà tellement 🥰", "Ma taille : à peine {fruit}, mais mon cœur est rempli de toi 💛"], "how": <String>["Super ! Il fait bien chaud et tout douillet ici 😌", "Ça va, maman. J'ai encore un peu grandi aujourd'hui 🌱", "Trop bien ! J'écoute ton cœur battre 💓"], "size": <String>["En ce moment, ma taille, c'est à peu près : {fruit} 😄", "Je mesure déjà {cm} cm ! Je grandis 📏", "Je suis à la semaine {week} et je grandis un peu chaque jour 🌱"], "kick_early": <String>["Je gigote déjà, mais je suis encore si petit que tu ne le sens pas 🤭", "Je fais des petites galipettes ici 🤸 Tu les sentiras bientôt !"], "kick": <String>["Tu as senti ? C'était moi 🦶", "J'ai dansé aujourd'hui, tu l'as senti ? 💃", "Ce petit coup de pied, c'était pour te dire coucou 👋🦶"], "hear_early": <String>["Mes oreilles se préparent encore, mais bientôt je t'entendrai 👂", "Laisse-moi grandir encore un peu, et j'entendrai ta voix 🥰"], "hear": <String>["Je t'entends, maman ! Parle-moi encore 🥰", "Ta voix, c'est ma musique préférée 🎶", "Chante-moi une chanson, je t'écoute 🎵"], "food": <String>["Tout ce que tu manges, j'y goûte un peu aussi 😋", "Et si on mangeait des fruits aujourd'hui ? 🍎", "Miam, c'était trop bon ! Encore un peu ? 😄"], "sleep": <String>["Moi aussi j'ai envie de dormir 😴 Reposons-nous ensemble", "Quand tu t'allonges, je me détends aussi 😌", "Pardon si je danse la nuit 🙈"], "dad": <String>["Fais un coucou à papa de ma part ! 👋", "Je connais aussi la voix de papa 😊", "J'adore quand papa parle à ton ventre 🥰"], "meet": <String>["Encore {weeks_left} semaines et on se rencontre ! 🤗", "Moi aussi j'ai hâte de te voir ! Laisse-moi grandir encore un peu 🌱", "On se rencontre bientôt 💛"], "meet_soon": <String>["Plus très longtemps, maman ! Je me prépare moi aussi 🤗", "Bientôt je serai dans tes bras 💛"], "name": <String>["Comment tu vas m'appeler ? 😊 Choisis un joli prénom !", "N'importe quel prénom sera joli dans ta voix 💛"], "hello": <String>["Coucou maman ! 👋", "Coucouuu ! Je t'attendais 💛"], "thanks": <String>["De rien, maman ! 😊", "Merci de me porter partout 💛"], "generic": <String>["Maman, tu es la meilleure 💛", "Je t'écoute 👂😊", "Hmm… je demanderai ça quand je serai plus grand 😄", "Je suis encore petit, mais j'ai adoré 😄", "Écris-moi encore, maman ! 🥰"], "care": <String>["Je t'aime tellement, maman 💛", "Je suis toujours avec toi 🤗"]}, "keywords": <String, O